import React,{useEffect,useRef,useState} from 'react';
import {AccessibilityInfo,Animated,Easing,Image,StyleSheet,View} from 'react-native';
// PWA reference: styles/home/home.css + member-repertoire.css.
// Locally generated, smooth PNG color/alpha stops, no WebView or new dependency.
const HEADER_GRADIENT='data:image/png;base64,';
const HEADER_BLOOM='data:image/png;base64,';
const HEADER_STREAK='data:image/png;base64,';
const BUTTON_SHEEN='data:image/png;base64,';
const BUTTON_LIGHT='data:image/png;base64,';
const BUTTON_DARK='data:image/png;base64,';
const BUTTON_PALE='data:image/png;base64,';
const FAMILY_GRADIENT='data:image/png;base64,';
const FAMILY_SHADE='data:image/png;base64,';
function useReducedMotion(){
 const [reduced,setReduced]=useState(false);
 useEffect(()=>{let live=true;void AccessibilityInfo.isReduceMotionEnabled().then(v=>{if(live)setReduced(v);}).catch(()=>{});
  const sub=AccessibilityInfo.addEventListener('reduceMotionChanged',setReduced);
  return()=>{live=false;sub.remove();};},[]);
 return reduced;
}
function useMotion(duration:number,reduced:boolean){
 const phase=useRef(new Animated.Value(0)).current;
 useEffect(()=>{
  phase.setValue(0);if(reduced)return;
  // One native timing loop, not JS frame updates; no list interaction lock.
  const a=Animated.loop(Animated.timing(phase,{toValue:1,duration,easing:Easing.linear,useNativeDriver:true,isInteraction:false}));
  a.start();return()=>a.stop();
 },[phase,duration,reduced]);
 return phase;
}
export function NativeHeaderLight(){
 const reduced=useReducedMotion(),[size,setSize]=useState({width:0,height:0});
 const sweep=useMotion(4600,reduced),bloom=useMotion(5300,reduced);
 const {width,height}=size;
 const x=sweep.interpolate({inputRange:[0,.75,1],outputRange:[0,width*1.225,width*1.225]});
 const opacity=sweep.interpolate({inputRange:[0,.75,.85,1],outputRange:[.92,.78,0,0]});
 const bx=bloom.interpolate({inputRange:[0,.5,1],outputRange:[-width*.094,width*.975,-width*.094]});
 const bo=bloom.interpolate({inputRange:[0,.5,1],outputRange:[.42,.9,.42]});
 return <View pointerEvents="none" style={s.fill} onLayout={e=>setSize(e.nativeEvent.layout)}>
  <Image source={{uri:HEADER_GRADIENT}} resizeMode="stretch" style={s.fill}/>
  {width>0&&height>0&&<><Animated.Image source={{uri:HEADER_BLOOM}} resizeMode="stretch"
   style={{position:'absolute',width:width*.78,height:height*2.95,left:-width*.35,top:-height*.85,
    opacity:reduced ? .2 : bo,transform:[{translateX:reduced?0:bx},{rotate:'-13deg'}]}}/>
   <Animated.Image source={{uri:HEADER_STREAK}} resizeMode="stretch"
   style={{position:'absolute',width:width*.5,height:15,left:-width*.17,top:height*.76-6,
    opacity:reduced ? .34 : opacity,transform:[{translateX:reduced?width*.3:x},{rotate:'-12deg'}]}}/></>}
 </View>;
}
export function NativeButtonLight({selected=false,pale=false}:{selected?:boolean;pale?:boolean}){
 const reduced=useReducedMotion(),[width,setWidth]=useState(0);
 const flow=useMotion(5800,reduced),sweep=useMotion(4600,reduced);
 const x=flow.interpolate({inputRange:[0,.5,1],outputRange:[0,-width*.8,0]});
 const glint=sweep.interpolate({inputRange:[0,.49,1],outputRange:[-width*.5,width*1.2,width*1.2]});
 const opacity=sweep.interpolate({inputRange:[0,.49,.6,1],outputRange:[.55,.65,0,0]});
 return <View pointerEvents="none" style={s.fill} onLayout={e=>setWidth(e.nativeEvent.layout.width)}>
  <Image source={{uri:selected?BUTTON_DARK:pale?BUTTON_PALE:BUTTON_LIGHT}} resizeMode="stretch" style={s.fill}/>
  {width>0&&!reduced&&<><Animated.Image source={{uri:selected?BUTTON_DARK:pale?BUTTON_PALE:BUTTON_LIGHT}} resizeMode="stretch"
   style={{position:'absolute',top:0,bottom:0,left:0,width:width*1.8,height:'100%',transform:[{translateX:x}]}}/>
   <Animated.Image source={{uri:BUTTON_SHEEN}} resizeMode="stretch"
    style={{position:'absolute',top:'-45%',left:0,width:width*.5,height:'190%',opacity,
      transform:[{translateX:glint},{rotate:'15deg'}]}}/></>}
 </View>;
}
export function NativeAlbumGradient(){return <Image pointerEvents="none" source={{uri:FAMILY_GRADIENT}} resizeMode="stretch" style={s.fill}/>;}
export function NativeAlbumShade(){return <Image pointerEvents="none" source={{uri:FAMILY_SHADE}} resizeMode="stretch" style={s.shade}/>;}
const s=StyleSheet.create({fill:{position:'absolute',top:0,right:0,bottom:0,left:0,width:'100%',height:'100%'},shade:{position:'absolute',top:'34%',bottom:0,left:0,right:0,width:'100%',height:'66%'}});
